static
void kernel_bicg(int m, int n,
		 DATA_TYPE POLYBENCH_2D(A,N,M,n,m),
		 DATA_TYPE POLYBENCH_1D(s,M,m),
		 DATA_TYPE POLYBENCH_1D(q,N,n),
		 DATA_TYPE POLYBENCH_1D(p,M,m),
		 DATA_TYPE POLYBENCH_1D(r,N,n))
{
  int i, j;

#pragma scop
  for (i = 0; i < _PB_M; i++)
    s[i] = 0;

  for (i = 0; i < _PB_N; i++)
    {
      q[i] = SCALAR_VAL(0.0);
      const DATA_TYPE ri = r[i];
      const DATA_TYPE* row = A[i];

      j = 0;
      while (j < _PB_M)
	{
	  size_t vl = __riscv_vsetvl_e64m1((size_t)(_PB_M - j));

	  vfloat64m1_t vs = __riscv_vle64_v_f64m1(&s[j], vl);
	  vfloat64m1_t vp = __riscv_vle64_v_f64m1(&p[j], vl);
	  vfloat64m1_t vA = __riscv_vle64_v_f64m1(&row[j], vl);

	  vfloat64m1_t vri = __riscv_vfmv_v_f_f64m1(ri, vl);
	  vfloat64m1_t vq = __riscv_vfmv_v_f_f64m1(0.0, vl);

	  vfloat64m1_t vprod = __riscv_vfmul_vv_f64m1(vA, vp, vl);
	  vfloat64m1_t vsum = __riscv_vfmacc_vv_f64m1(vs, vri, vprod, vl);
	  vfloat64m1_t vq2 = __riscv_vfmacc_vv_f64m1(vq, vA, vprod, vl);

	  __riscv_vse64_v_f64m1(&s[j], vsum, vl);
	  __riscv_vse64_v_f64m1(&q[i], vq2, vl);

	  j += (int)vl;
	}
    }
#pragma endscop
}

