static
void kernel_floyd_warshall(int n,
			   DATA_TYPE POLYBENCH_2D(path,N,N,n,n))
{
  int i, j, k;

#pragma scop
  for (k = 0; k < _PB_N; k++)
    {
      const DATA_TYPE* __restrict__ rowk = path[k];

      for (i = 0; i < _PB_N; i++)
	{
	  DATA_TYPE* __restrict__ rowi = path[i];
	  const DATA_TYPE dik = rowi[k];

	  int j = 0;
	  while (j < _PB_N)
	    {
	      size_t vl = __riscv_vsetvl_e32m8((size_t)(_PB_N - j));

	      vfloat32m8_t vi = __riscv_vle32_v_f32m8((const float*)(rowi + j), vl);
	      vfloat32m8_t vk = __riscv_vle32_v_f32m8((const float*)(rowk + j), vl);

	      vfloat32m8_t vdik = __riscv_vfmv_v_f_f32m8(dik, vl);
	      vfloat32m8_t vsum = __riscv_vfadd_vv_f32m8(vdik, vk, vl);

	      vbool4_t mask = __riscv_vmslt_vv_f32m8_b4(vi, vsum, vl);
	      vfloat32m8_t vres = __riscv_vmerge_vvm_f32m8(vi, vsum, mask, vl);

